// Mismos IDs que en 'Config GHL (lead)'
const etapas = {
  nuevo_lead: 'ID_ETAPA_1',
  contactado: 'ID_ETAPA_2',
  calificado: 'ID_ETAPA_3',
  cotizacion_enviada: 'ID_ETAPA_4',
  seguimiento: 'ID_ETAPA_5',
  anticipo_pagado: 'ID_ETAPA_6',
  pago_completo: 'ID_ETAPA_7',
  viaje_en_curso: 'ID_ETAPA_8',
  post_viaje: 'ID_ETAPA_9'
};

return $input.all().map((item) => {
  const body = item.json.body ?? {};
  const stageId = etapas[body.etapa];
  if (!body.opportunityId) throw new Error('Falta opportunityId');
  if (!stageId && !body.perdido) throw new Error(`Etapa desconocida: ${body.etapa}. Usa: ${Object.keys(etapas).join(', ')}`);

  const update = {};
  if (stageId) update.pipelineStageId = stageId;
  // Venta cerrada al pagar el anticipo; perdido si el cliente desiste
  if (body.perdido) update.status = 'lost';
  else if (['anticipo_pagado', 'pago_completo', 'viaje_en_curso', 'post_viaje'].includes(body.etapa)) update.status = 'won';
  else update.status = 'open';
  if (body.monto) update.monetaryValue = Number(body.monto);

  return { json: { opportunityId: body.opportunityId, update } };
});
